BEGIN;

-- G検定 Set H (g-kentei-h) ブロック1: q1〜q16
-- ネオコグニトロン〜CPU/GPU/TPU。カテゴリ2×2, 3×2, 4×12。viz 7問・calc 1問(q4)。
-- subject/categories は作成済み。questions の INSERT のみ。

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES
  ('g-kentei-h-q1', '2. 人工知能をめぐる動向',
   '福島邦彦が1980年前後に提案した、視覚野の「単純細胞」と「複雑細胞」の働きをまねた階層型のネットワークで、現在のCNN(畳み込みニューラルネットワーク)の原型とされるものはどれか。',
   NULL::text,
   '["ネオコグニトロン（単純細胞と複雑細胞の働きをまねた階層型モデル）", "パーセプトロン（1958年に考案された最も基本的な単層の分類モデル）", "LeNet（1998年に実用化された手書き文字認識のCNNモデル）", "多層パーセプトロン（隠れ層を持つ全結合のネットワークモデル）"]',
   0,
   '[0]',
   'single',
   '{"asked": "CNNの原型となった、視覚野をまねた古いネットワークの名前を問う。", "point": "「単純細胞・複雑細胞をまねた」「CNNの原型」と来たらネオコグニトロン。", "kid": "目の中で、まず線や角を見つける係(単純細胞)と、それを組み合わせて「多少ズレても同じ形」と判断する係(複雑細胞)がいる。この2段構えを機械でまねたのがネオコグニトロン。", "eg": "似顔絵を描くとき、まず輪郭や目・鼻・口のパーツを1つずつ拾い、次に「多少パーツの位置がズレていても同じ人だ」とまとめる。この2段階の仕事を係分担にしたイメージ。", "terms": [["単純細胞", "線や角など、決まった向きの模様に反応する視覚野の神経細胞"], ["複雑細胞", "単純細胞の反応をまとめ、多少位置がズレても同じ形だと判断する視覚野の神経細胞"], ["CNN", "Convolutional Neural Network＝畳み込みニューラルネットワーク。画像認識で定番のネットワーク"]], "think": "なぜCNNの前にネオコグニトロンが要るのかがカギ。当時は「画像のどこに線があるか」をコンピュータにどう見つけさせるかが課題だった。福島は、脳の視覚野が単純細胞で局所的な特徴を拾い、複雑細胞でその特徴を位置ズレに強い形でまとめるという2段構えで物を認識していることに注目し、それを層構造のネットワークとして再現した。この「局所特徴を拾う層」と「まとめて位置ズレに強くする層」の組み合わせが、そのまま後のCNNの畳み込み層とプーリング層の設計につながった。だから原型と呼ばれる。", "vs": "パーセプトロンは1958年に考案された単層の分類モデルで、視覚野の階層構造をまねたものではない。多層パーセプトロンは隠れ層を持つ全結合のネットワークで、画像の位置ズレへの強さを狙った設計ではない点がネオコグニトロンと異なる。LeNetは実際に手書き文字認識で使われた実用CNNで、ネオコグニトロンより後の1998年に登場した、より具体的な実装である。", "why_asked": "CNNの歴史というとLeNetやAlexNetが先に浮かびやすいが、その前段としてネオコグニトロンが視覚野の仕組みを最初にネットワークへ落とし込んだ点を押さえているかが問われる。", "usecase": "現在のCNNが持つ「畳み込みで特徴を拾い、プーリングで位置ズレに強くする」という基本設計の由来を理解する手がかりになる。", "opt": ["正解。単純細胞・複雑細胞の2段構えをまねた階層型モデルで、CNNの原型とされる。", "1958年に考案された単層の分類モデルで、視覚野の階層構造をまねたものではない。", "1998年に実用化された手書き文字認識のCNNで、ネオコグニトロンより後の具体的な実装。", "隠れ層を持つ全結合のネットワークで、画像の位置ズレへの強さを狙った設計ではない。"]}'),  ('g-kentei-h-q2', '2. 人工知能をめぐる動向',
   '1986年にラメルハートらが論文で示したことで広く知られるようになり、多層ニューラルネットワークの学習を実用化して第2次AIブームを支えた手法はどれか。',
   NULL::text,
   '["誤差逆伝播法（出力側の誤差を逆向きに伝えて各層の重みを直す手法）", "遺伝的アルゴリズム（生物の進化のしくみをまねた探索的な最適化手法）", "エキスパートシステム（専門家の知識をルールとして大量に蓄えた仕組み）", "ボルツマンマシン（確率的に状態を更新して学習する初期のネットワーク）"]',
   0,
   '[0]',
   'single',
   '{"asked": "1986年の論文で広まり、第2次AIブームを支えた学習手法の名前を問う。", "point": "「1986年」「ラメルハートら」「多層NNの学習を実用化」と来たら誤差逆伝播法。", "kid": "多層のネットワークが出した答えの間違い具合を、出口側から入口側へ順番に伝えながら、各層のつまみ(重み)を少しずつ直していくやり方。これが1986年の論文で広く知られるようになった。", "eg": "テストの答案返却で、最終的な点数の悪さの原因を、最後の設問から順に1つずつさかのぼって「どの問題の解き方が悪かったか」を突き止めていくイメージ。", "terms": [["連鎖律", "微分の計算で、途中の変化率を鎖のようにかけ合わせてまとめて求める数学の考え方。誤差逆伝播法の計算の基礎になる"], ["第2次AIブーム", "1980年代、専門知識をルール化したエキスパートシステムが中心だったAIの盛り上がりの時期"]], "think": "なぜ1986年が節目なのかがカギ。誤差逆伝播法の考え方自体はそれ以前にも提案されていたが、当時は多層ネットワークをどう効率よく学習させるかが実務上の壁だった。ラメルハートらの1986年の論文は、連鎖律を使えば出力側の誤差から入力側までの各重みの勾配を効率よく計算できることを具体的に示し、多層ネットワークの学習を実用的なものにした。この論文をきっかけに研究者の関心が高まり、当時のAIの主流だったエキスパートシステムと並んでニューラルネットワーク研究が再評価される流れができた。だから第2次AIブームを支えた技術として語られる。", "vs": "エキスパートシステムは同じ第2次AIブームの中心技術だが、専門家の知識をルールとして人手で蓄える仕組みであり、誤差逆伝播法のようにデータから重みを自動で調整する学習手法ではない。遺伝的アルゴリズムやボルツマンマシンも同時期に研究された手法だが、1986年のラメルハートらの論文で広く知られるようになったのは誤差逆伝播法である。", "why_asked": "誤差逆伝播法の計算の仕組み自体はカテゴリ4で問われやすいが、それが「いつ」「誰によって」広まり、AIの歴史の中でどう位置づくかは見落とされやすいため、歴史文脈で問われる。", "usecase": "現在のディープラーニングの学習は、規模は違えどこの誤差逆伝播法の考え方をそのまま使っている。歴史を知ると、なぜ勾配消失などの問題が今も語られるのかの背景が見えてくる。", "opt": ["正解。1986年のラメルハートらの論文で広まり、多層NNの学習を実用化した。", "生物の進化のしくみをまねた最適化手法で、誤差を逆向きに伝える仕組みとは別物。", "専門家の知識をルールとして蓄えた仕組みで、データから重みを学習する手法ではない。", "確率的に状態を更新する初期のネットワークで、1986年の論文とは別の系統の手法。"]}'),  ('g-kentei-h-q3', '3. 機械学習の概要',
   '単純パーセプトロンは、2つのグループを1本の直線（多次元では平面）で完全に分けられる配置なら学習できるが、XORのようにそれができない配置では正しく分類できない。この「1本の線で分けられる性質」を指す語はどれか。',
   NULL::text,
   '["線形分離可能性（1本の直線や平面で完全に分けられる性質）", "過学習（訓練データの細部に寄りすぎて未知データに弱くなる状態）", "次元の呪い（次元が増えるほどデータがまばらになる問題）", "バイアス・バリアンス（単純さと複雑さの間のトレードオフ）"]',
   0,
   '[0]',
   'single',
   '{"asked": "単純パーセプトロンが学習できる/できないの境目になる性質の名前を問う。", "point": "「1本の直線(平面)で完全に分けられるか」を指すのが線形分離可能性。", "kid": "2つのグループが、間に1本の線をまっすぐ引くだけできれいに分けられるとき、そのデータは「線形分離可能」と言う。", "eg": "紙の上に赤い点と青い点をばらまいたとき、1本の直線を引くだけで赤と青を完全に仕分けられるなら線形分離可能。点がぐちゃぐちゃに混ざっていて、どう直線を引いても両方の色がはみ出るなら線形分離できない。", "terms": [["単純パーセプトロン", "1958年に考案された、入力に重みを掛けて足し合わせ、しきい値で0/1を出す最も基本的なニューラルネットワーク"], ["XOR", "eXclusive OR＝排他的論理和。2つの入力が同じなら0、違えば1を返す、直線1本では分けられない代表例"]], "think": "なぜXORが単純パーセプトロンの限界を示す例になるのかがカギ。単純パーセプトロンは、入力を重み付きで足し合わせた値をしきい値で0/1に振り分けるだけの仕組みで、これは幾何学的には「1本の直線(平面)を引いて両側に分ける」ことしかできない。XORの4通りの入力を平面上に置くと、同じ答えどうしが対角線上に配置され、どう直線を引いても必ずどちらかの答えが混ざってしまう。つまりXORは線形分離可能ではない。だから単純パーセプトロン1層では解けず、隠れ層を挟んで複数の直線を組み合わせる多層パーセプトロンが必要になった。", "vs": "過学習は訓練データに寄りすぎて未知データで成績が落ちる現象で、分けられる形そのものの限界とは別の話。次元の呪いはデータの次元が増えることで起きる問題で、線を引けるかどうかとは無関係。バイアス・バリアンスはモデルの単純さと複雑さのトレードオフを指す語で、線形分離可能性のような幾何学的な性質を表す語ではない。", "why_asked": "「単純パーセプトロンはXORが解けない」という事実だけを覚えていても、その理由となる「線形分離可能性」という語を結びつけていないと、言い換えの問題で答えられなくなるため。", "usecase": "ある問題が単純な線形モデルで解けそうか、それとも層を増やしたり非線形な工夫が要りそうかを見積もる最初の判断材料になる。", "opt": ["正解。1本の直線(平面)で完全に分けられる性質のこと。", "訓練データの細部に寄りすぎて未知データに弱くなる状態で、分けられる形の限界とは別の話。", "次元が増えるほどデータがまばらになる問題で、線を引けるかどうかとは無関係。", "モデルの単純さと複雑さの間のトレードオフを指す語で、幾何学的な性質の名前ではない。"], "viz": "<svg viewBox=\"0 0 340 148\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"14\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">1本の線で分けられるか、分けられないか</text><text x=\"85\" y=\"28\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">線形分離できる</text><circle cx=\"50\" cy=\"60\" r=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><circle cx=\"65\" cy=\"75\" r=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><circle cx=\"45\" cy=\"85\" r=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><circle cx=\"110\" cy=\"50\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><circle cx=\"125\" cy=\"65\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><circle cx=\"115\" cy=\"90\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><line x1=\"75\" y1=\"40\" x2=\"95\" y2=\"100\" stroke=\"#e8eaf0\" stroke-width=\"1.6\"/><text x=\"85\" y=\"118\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">1本の直線で2組に分けられる</text><line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"128\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"255\" y=\"28\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\">線形分離できない(XOR)</text><circle cx=\"225\" cy=\"50\" r=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><circle cx=\"285\" cy=\"90\" r=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><circle cx=\"285\" cy=\"50\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><circle cx=\"225\" cy=\"90\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"255\" y=\"118\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">どう1本引いても混ざってしまう</text><text x=\"170\" y=\"138\" fill=\"#c9a04a\" font-size=\"9\" text-anchor=\"middle\">単純パーセプトロンは右側の配置を解けない</text></svg>"}'),  ('g-kentei-h-q4', '3. 機械学習の概要',
   '1つのニューロンは、複数の入力それぞれに重みを掛けて足し合わせ、そこにバイアスを加えた値を活性化関数に通して出力を作る。この「入力×重みの合計にバイアスを加える」計算を何と呼ぶか。',
   NULL::text,
   '["重み付き総和（各入力に重みを掛けて足し合わせ、バイアスを加えた値）", "活性化関数（重み付き総和を非線形に変換して次の層へ渡す部品）", "誤差逆伝播（出力側の誤差を逆向きに伝えて各層の重みを直す計算のこと）", "正則化項（重みの大きさに応じて誤差の値へ加える罰則のための項）"]',
   0,
   '[0]',
   'single',
   '{"asked": "1つのニューロンが最初に行う「入力×重み＋バイアス」の計算の名前を問う。", "point": "「入力×重みを足してバイアスを加える」の段階が重み付き総和。活性化関数はその後。", "kid": "それぞれの入力に「効き具合のつまみ(重み)」を掛けて全部足し、最後に下駄(バイアス)を履かせて1つの数にまとめる計算。", "eg": "何科目かのテストの点数(入力)に、科目ごとの重要度(重み)を掛けて合計し、最後にげた履き点(バイアス)を足して総合点を出すイメージ。", "terms": [["重み", "各入力がどれだけ結果に効くかを決める、掛け算する数（つまみのようなもの）"], ["バイアス", "重み付き総和に一律で足す下駄のような値。ちょうど良い基準点をずらす役目"], ["活性化関数", "重み付き総和をそのまま流さず、非線形に変換して出力にする部品"]], "think": "なぜ活性化関数の前にこの計算が要るのかがカギ。ニューロンは何もない状態では、複数の入力をどう扱えばいいか分からない。そこで、各入力に「効き具合」を表す重みを掛けて足し合わせ、さらにバイアスという一律の下駄を加えることで、入力全体を1つの数値にまとめる。この数値をそのまま出力にすると直線的な計算しかできないため、次の段階で活性化関数に通して曲げることで、複雑な境界も表現できるようにする。つまり重み付き総和は「情報を1つにまとめる係」、活性化関数は「まとめた情報を使いやすい形に変換する係」という役割分担になっている。", "vs": "活性化関数は重み付き総和の後工程で、非線形に変換する部品であり、足し合わせる計算そのものではない。誤差逆伝播は学習時に誤差を逆向きに伝えて重みを直す計算で、順伝播で出力を作るこの計算とは向きも役割も逆。正則化項は重みが大きくなりすぎないよう誤差に加える罰則であり、ニューロン1つの出力計算には登場しない。", "why_asked": "「活性化関数」という言葉だけが独り歩きしがちで、その手前にある「重み付き総和」という計算段階の名前と役割を区別できているかが問われる。", "usecase": "ニューラルネットワークの計算の流れを、入力から出力まで1ステップずつ追えるようになる基礎。誤差逆伝播法の勾配計算も、この重み付き総和を出発点にたどることになる。", "opt": ["正解。各入力に重みを掛けて足し合わせ、バイアスを加えた値のこと。", "重み付き総和を非線形に変換して出力にする部品で、足し合わせる計算そのものではない。", "学習時に誤差を逆向きに伝えて重みを直す計算で、出力を作るこの計算とは向きが逆。", "重みが大きくなりすぎないよう誤差に加える罰則で、ニューロン1つの出力計算には登場しない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">入力×重みを足し合わせ、バイアスを加える</text><circle cx=\"50\" cy=\"45\" r=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"30\" y=\"48\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">x1=2</text><circle cx=\"50\" cy=\"95\" r=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"30\" y=\"98\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"end\">x2=3</text><line x1=\"55\" y1=\"45\" x2=\"165\" y2=\"68\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"105\" y=\"50\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">w1=0.5</text><line x1=\"55\" y1=\"95\" x2=\"165\" y2=\"72\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"105\" y=\"92\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">w2=1</text><circle cx=\"180\" cy=\"70\" r=\"20\" fill=\"none\" stroke=\"#e8eaf0\" stroke-width=\"1.6\"/><text x=\"180\" y=\"68\" fill=\"#e8eaf0\" font-size=\"13\" text-anchor=\"middle\" font-weight=\"600\">Σ</text><text x=\"180\" y=\"97\" fill=\"#c9a04a\" font-size=\"7.5\" text-anchor=\"middle\">+バイアス1</text><line x1=\"200\" y1=\"70\" x2=\"250\" y2=\"70\" stroke=\"#6ab08d\" stroke-width=\"1.6\"/><circle cx=\"265\" cy=\"70\" r=\"12\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"265\" y=\"73\" fill=\"#6ab08d\" font-size=\"11\" text-anchor=\"middle\" font-weight=\"600\">z</text><text x=\"180\" y=\"118\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">z = 2×0.5 + 3×1 + 1 = 5</text><text x=\"180\" y=\"132\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">この後、活性化関数に通して出力にする</text></svg>", "calc": "入力      x1=2   x2=3\n重み      w1=0.5 w2=1\n入力×重み  2×0.5=1   3×1=3\n足し合わせ 1+3 = 4\n+バイアス  4+1 = 5   ← これが重み付き総和z\n記号版: z = w1x1 + w2x2 + b = 0.5×2 + 1×3 + 1 = 5"}'),  ('g-kentei-h-q5', '4. ディープラーニングの概要',
   'ReLU関数は入力が負のとき出力も勾配も常に0になり、そのノードが二度と更新されなくなる「dying ReLU」を招くことがある。この対策として、入力が負の領域にもごくわずかな傾きを残した活性化関数はどれか。',
   NULL::text,
   '["Leaky ReLU関数（負の領域にもごくわずかな傾きを残す関数）", "シグモイド関数（出力を0〜1の範囲に押し込む滑らかな活性化関数）", "tanh関数（出力を-1〜1の範囲に押し込む滑らかな活性化関数）", "ソフトマックス関数（複数の出力を合計1の確率へ変換する活性化関数）"]',
   0,
   '[0]',
   'single',
   '{"asked": "dying ReLU対策として、負の領域にわずかな傾きを残した活性化関数の名前を問う。", "point": "「負の領域にもわずかな傾きを残す」と来たらLeaky ReLU。", "kid": "ReLUは入力がマイナスならぴったり0にして、そこから先は何も反応しない。Leaky ReLUはマイナスのときも完全に0にせず、ほんの少しだけ傾きを残しておく。", "eg": "ReLUは「マイナスの意見は完全に無視する上司」。Leaky ReLUは「マイナスの意見もごく小さくは聞いておく上司」。少しでも反応が残っていれば、あとで見直すきっかけが作れる。", "terms": [["ReLU", "Rectified Linear Unit＝正規化線形ユニット。入力が正ならそのまま、負なら0を返す活性化関数"], ["dying ReLU", "入力がずっと負のノードで出力も勾配も0のままになり、そのノードの重みが二度と更新されなくなる現象"]], "think": "なぜdying ReLUが起きるのかがカギ。ReLUは負の入力に対して出力を0にし、そのときの勾配（傾き）も0にする。学習の途中であるノードへの入力がずっと負になってしまうと、そのノードの勾配は常に0のままとなり、誤差逆伝播で重みを直す合図がまったく届かなくなる。つまりそのノードは死んだように動かなくなる。Leaky ReLUは負の領域の傾きを0ではなくごくわずかな値（例えば0.01倍）にすることで、負の入力が続いても勾配がわずかに残るようにし、そのノードが完全に更新不能になるのを防ぐ。", "vs": "シグモイド関数とtanh関数はどちらも出力を一定の範囲に押し込む滑らかな関数で、値そのものは負でも滑らかに変化するが、層が深いと勾配消失を起こしやすいという別の弱点を持つ。ソフトマックス関数は複数の出力を合計1の確率に変換する関数で、出力層で使うものであり、dying ReLU対策とは目的が異なる。", "why_asked": "ReLUの利点（勾配消失を起こしにくい）ばかりが強調されがちで、その裏返しの弱点であるdying ReLUと、その対策としてのLeaky ReLUの組み合わせが問われやすい。", "usecase": "中間層で活性化関数を選ぶとき、ReLUで学習が途中から進まなくなった場合の代替候補として使う。", "opt": ["正解。負の領域にもごくわずかな傾きを残し、勾配が完全に0になるのを防ぐ。", "出力を0〜1の範囲に押し込む滑らかな関数で、dying ReLU対策とは別の弱点(勾配消失)を持つ。", "出力を-1〜1の範囲に押し込む滑らかな関数で、こちらも層が深いと勾配消失を起こしやすい。", "複数の出力を合計1の確率に変換する出力層向けの関数で、中間層のdying ReLU対策ではない。"], "viz": "<svg viewBox=\"0 0 340 138\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">負の側を0で止めるか、わずかに傾けるか</text><text x=\"75\" y=\"28\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">ReLU関数</text><line x1=\"30\" y1=\"100\" x2=\"90\" y2=\"100\" stroke=\"#c47070\" stroke-width=\"1.6\"/><line x1=\"90\" y1=\"100\" x2=\"140\" y2=\"40\" stroke=\"#c47070\" stroke-width=\"1.6\"/><text x=\"85\" y=\"118\" fill=\"#c47070\" font-size=\"8.5\" text-anchor=\"middle\">負側は出力も勾配も0</text><line x1=\"170\" y1=\"24\" x2=\"170\" y2=\"122\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"255\" y=\"28\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">Leaky ReLU関数</text><line x1=\"200\" y1=\"108\" x2=\"260\" y2=\"100\" stroke=\"#6ab08d\" stroke-width=\"1.6\"/><line x1=\"260\" y1=\"100\" x2=\"310\" y2=\"40\" stroke=\"#6ab08d\" stroke-width=\"1.6\"/><text x=\"255\" y=\"118\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">負側にもわずかな傾きを残す</text></svg>"}'),  ('g-kentei-h-q6', '4. ディープラーニングの概要',
   '2つの確率分布がどれだけ異なっているかを数値で表す指標で、VAE(変分オートエンコーダ)の学習や知識蒸留などで、ある分布をお手本の分布へどれだけ近づけられたかを測るために使われるものはどれか。',
   NULL::text,
   '["カルバック・ライブラー情報量（2つの確率分布のズレの大きさを表す指標）", "平均二乗誤差（予測値と正解値との差を2乗して平均した回帰向けの誤差）", "交差エントロピー（予測確率と正解ラベルとのズレを表す分類向けの誤差指標）", "コサイン類似度（2つのベクトルが向く方向の近さの度合いを表す指標）"]',
   0,
   '[0]',
   'single',
   '{"asked": "2つの確率分布のズレを測る指標で、VAEや知識蒸留に使われるものの名前を問う。", "point": "「2つの確率分布のズレ」「お手本の分布に近づける」と来たらKLダイバージェンス。", "kid": "2つの山の形をした確率の分布があるとき、その山の位置や高さがどれだけ違うかを1つの数値にしたもの。ぴったり同じ形なら0になる。", "eg": "自分の描いた地図(分布Q)と、正確な地図(分布P)を重ねて、どれだけずれているかを数値化するイメージ。ずれが大きいほど数値も大きくなる。", "terms": [["KLダイバージェンス", "Kullback-Leibler divergence＝カルバック・ライブラー情報量。2つの確率分布の隔たりを表す指標"], ["VAE", "Variational Autoencoder＝変分オートエンコーダ。データを確率分布として圧縮し、そこから新しいデータも生成できるネットワーク"]], "think": "なぜ「誤差」ではなく「分布どうしのズレ」という別の測り方が要るのかがカギ。平均二乗誤差や交差エントロピーは、1つの正解値や正解ラベルとの近さを測るのに向いている。しかしVAEでは、学習で作った分布Qを、あらかじめ決めておいたお手本の分布P(多くは正規分布)にできるだけ近づけたい、という「分布どうしの近さ」を測る必要がある。KLダイバージェンスは、2つの分布の対応する点どうしで確率の比を取り、その差の大きさを積み上げることで、分布全体としてどれだけ形がずれているかを1つの数値にする。この値を小さくするよう学習することで、Qは徐々にPに近づいていく。", "vs": "平均二乗誤差は数値どうしの差を測る回帰向けの誤差で、確率分布の形のズレを測るものではない。交差エントロピーは正解ラベルとの確率のズレを測る分類でおなじみの誤差だが、KLダイバージェンスとは式の作り方が異なり、2つの任意の分布どうしを比べる用途で使われるのは主にKLダイバージェンス側である。コサイン類似度はベクトルの向きの近さを測る指標で、確率分布のズレを測るものではない。", "why_asked": "生成AI関連の出題増加にともない、VAEの仕組みを説明する用語としてKLダイバージェンスが問われやすく、平均二乗誤差や交差エントロピーとの使い分けが盲点になりやすい。", "usecase": "VAEの学習で「作った分布をお手本の分布にどれだけ近づけられたか」を評価する項目や、大きなモデルの出力分布を小さなモデルにまねさせる知識蒸留で使われる。", "opt": ["正解。2つの確率分布のズレの大きさを表す指標で、VAEや知識蒸留で使われる。", "予測値と正解値の差を2乗して平均した誤差で、確率分布どうしのズレを測るものではない。", "予測確率と正解ラベルとのズレを表す誤差で、分類でよく使うが分布どうしの比較用ではない。", "2つのベクトルの向きの近さを表す指標で、確率分布のズレを測るものではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">2つの確率分布の形のズレを数値にする</text><path d=\"M20 90 C 60 90, 75 40, 110 40 C 145 40, 160 90, 200 90\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"90\" y=\"30\" fill=\"#60a5fa\" font-size=\"8.5\" text-anchor=\"middle\">お手本の分布 P</text><path d=\"M60 90 C 100 90, 115 55, 150 55 C 185 55, 200 90, 240 90\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\" stroke-dasharray=\"3 2\"/><text x=\"230\" y=\"45\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">近づけたい分布 Q</text><line x1=\"20\" y1=\"90\" x2=\"320\" y2=\"90\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"170\" y=\"112\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">山の位置・高さがずれているほどKLは大きくなる</text><text x=\"170\" y=\"128\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">Qを学習でPに近づけるほどKLは0に近づく</text></svg>"}'),  ('g-kentei-h-q7', '4. ディープラーニングの概要',
   '似ているデータどうしの埋め込み(ベクトル表現)を近づけ、似ていないデータどうしは遠ざけるように学習させる誤差関数群を何と呼ぶか。',
   NULL::text,
   '["Contrastive・Triplet Loss（似た物同士を近く違う物を遠ざける誤差）", "交差エントロピー（予測確率と正解ラベルの確率とのズレの大きさを表す分類でおなじみの誤差）", "平均二乗誤差（予測した数値と正解の数値との差を2乗して平均した回帰でおなじみの誤差）", "カルバック・ライブラー情報量（2つの確率分布そのものの形のズレの大きさを表す指標）"]',
   0,
   '[0]',
   'single',
   '{"asked": "似た物を近づけ違う物を遠ざけるよう学習させる誤差関数群の名前を問う。", "point": "「似た物を近く、違う物を遠くに埋め込む」と来たらContrastive Loss・Triplet Loss。", "kid": "写真をベクトル(座標のようなもの)に変換するとき、同じ人の写真どうしは近い場所に、違う人の写真どうしは遠い場所に来るように学習させる誤差の測り方。", "eg": "教室の座席替えで、仲の良い友達どうしは近くの席に、あまり関わりのない人とは離れた席になるよう並べ直すイメージ。写真の埋め込み空間でも同じことをする。", "terms": [["Contrastive Loss", "対照的な損失。2つのデータが似ているか違うかのペアを比べ、似ていれば近づけ違えば遠ざけるよう学習させる誤差"], ["Triplet Loss", "三つ組の損失。基準・似ている例・似ていない例の3つを1組にして、基準を似ている例に近づけ似ていない例から遠ざける誤差"], ["埋め込み", "データを、意味の近さが距離に反映されるベクトル(座標のようなもの)として表すこと"]], "think": "なぜ正解ラベルとの誤差ではなく、データどうしの距離で学習させるのかがカギ。顔認証のように「同一人物かどうか」を判定したい場面では、クラスの数があらかじめ決まっていなかったり、1人あたりの写真が少なかったりして、通常の分類のように正解ラベルとの誤差を測る方法がうまく使えないことがある。そこでContrastive LossやTriplet Lossは、正解ラベルの代わりに「このペア(または三つ組)は似ているか違うか」という関係性そのものを誤差にする。似ているペアの距離が近ければ誤差は小さく、遠ければ誤差を大きくする。この学習を繰り返すことで、埋め込み空間の中に「似ている物どうしが自然に集まる地図」ができあがる。", "vs": "交差エントロピーと平均二乗誤差はどちらも1つの正解値や正解ラベルとの近さを測る誤差で、データどうしの距離関係を直接学習させるものではない。カルバック・ライブラー情報量は2つの確率分布のズレを測る指標であり、個々のデータ点どうしの埋め込み距離を扱うContrastive Loss・Triplet Lossとは対象が異なる。", "why_asked": "顔認証や画像検索の仕組みを、通常の分類と同じ誤差関数で学習していると誤解しやすく、データどうしの関係性を直接学習させる誤差関数群があることを問う。", "usecase": "顔認証、類似画像検索、レコメンドのように「同じ/似ている」を判定したいが、クラス数が固定できない場面で使われる。", "opt": ["正解。似ている物を近く、違う物を遠くに埋め込むよう学習させる誤差関数群。", "予測確率と正解ラベルとのズレを表す誤差で、データどうしの距離関係を直接学習させるものではない。", "予測値と正解値の差を2乗して平均した誤差で、こちらも距離関係を直接学習させるものではない。", "2つの確率分布のズレの大きさを表す指標で、個々のデータ点どうしの距離を扱うものではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"9.3\" text-anchor=\"middle\" font-weight=\"600\">似た物どうしを近づけ、違う物どうしを遠ざける</text><text x=\"80\" y=\"30\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">学習前</text><circle cx=\"50\" cy=\"60\" r=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"50\" y=\"78\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">犬A</text><circle cx=\"115\" cy=\"90\" r=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"115\" y=\"105\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">犬B</text><circle cx=\"85\" cy=\"55\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"85\" y=\"40\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">猫C</text><line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"128\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"255\" y=\"30\" fill=\"#8892a4\" font-size=\"9\" text-anchor=\"middle\">学習後</text><circle cx=\"235\" cy=\"75\" r=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><circle cx=\"250\" cy=\"80\" r=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"242\" y=\"100\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">犬どうしは接近</text><circle cx=\"305\" cy=\"40\" r=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"305\" y=\"30\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">猫は遠くへ</text><text x=\"170\" y=\"130\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">埋め込み空間で「似ている＝近い」を作る</text></svg>"}'),  ('g-kentei-h-q8', '4. ディープラーニングの概要',
   'L1正則化・L2正則化とはさらに違い、重みの大きさそのものではなく「値が0でない重みの個数」に直接ペナルティを課す正則化はどれか。',
   NULL::text,
   '["L0正則化（非ゼロの重みの個数そのものに罰則を課す正則化）", "L1正則化（重みの絶対値の合計に罰則を課す正則化）", "L2正則化（重みの2乗の合計に罰則を課す正則化）", "ドロップアウト（学習のたび一部のノードをランダムに無効化する手法）"]',
   0,
   '[0]',
   'single',
   '{"asked": "非ゼロの重みの個数そのものに罰則を課す正則化の名前を問う。", "point": "「重みの大きさではなく個数そのもの」に罰則ならL0正則化。", "kid": "重みが大きいか小さいかは気にせず、「そもそも使っている重みは何個あるか」の個数だけを数えて、多いほど罰を与える正則化。", "eg": "道具箱の中身を整理するとき、道具1つ1つの大きさは問わず、単純に「入っている道具の本数」を減らそうとするイメージ。L1やL2は道具の大きさを気にするが、L0は本数だけを気にする。", "terms": [["L0正則化", "L0 regularization。値が0でない重みの個数そのものに罰則を課す正則化"], ["L1正則化", "重みの絶対値の合計に罰則を課し、一部の重みをちょうど0にできる正則化"], ["L2正則化", "重みの2乗の合計に罰則を課し、重み全体をなだらかに小さくする正則化"]], "think": "なぜL1やL2ではなく個数そのものを数える発想が要るのかがカギ。L1正則化は重みの絶対値の合計を罰することで結果的に一部の重みを0にできるが、これはあくまで「大きさの合計」を小さくした副産物である。L0正則化はそれとは違い、最初から「0でない重みが何個あるか」という個数だけを直接数えて罰する。これにより、狙いどおりに使う重みの本数そのものを絞り込める。ただし個数を数える計算は微分ができず、勾配降下法での最適化が難しいという実用上の壁があり、その扱いにくさの代わりとしてL1正則化が使われることが多い。", "vs": "L1正則化は重みの絶対値の合計を罰し、結果的に一部の重みが0になるが、罰しているのはあくまで大きさの合計であって個数そのものではない。L2正則化は重みの2乗の合計を罰し、重みをちょうど0にはせずなだらかに小さくする。ドロップアウトは重みではなくノードを学習のたびランダムに無効化する手法で、罰則を課す正則化とは仕組みが異なる。", "why_asked": "L1・L2正則化は頻出だが、L0正則化は「個数そのもの」という他とは違う切り口を持つため、L1との違いを取り違えていないかを確認する目的で出やすい。", "usecase": "使う特徴量や重みの本数を厳密に絞り込みたい場面の理論的な出発点として理解しておく。", "opt": ["正解。値が0でない重みの個数そのものに罰則を課す正則化。", "重みの絶対値の合計に罰則を課す正則化で、個数ではなく大きさの合計を罰する。", "重みの2乗の合計に罰則を課す正則化で、重みをちょうど0にはせずなだらかに小さくする。", "学習のたび一部のノードをランダムに無効化する手法で、罰則を課す正則化ではない。"]}'),  ('g-kentei-h-q9', '4. ディープラーニングの概要',
   '回帰モデルにL1正則化を組み合わせ一部の係数をちょうど0にして特徴量を絞り込む手法と、L2正則化を組み合わせ係数全体をなだらかに小さくする手法は、それぞれ何と呼ばれるか。',
   NULL::text,
   '["ラッソ回帰とリッジ回帰（順にL1正則化つき回帰、L2正則化つき回帰）", "決定木と勾配ブースティング（枝分かれによる予測と、その逐次的な改良）", "主成分分析とk-means法（次元削減と、教師なしのグループ分け手法）", "バギングとブースティング（並列な多数決と、逐次的な誤りの補正手法）"]',
   0,
   '[0]',
   'single',
   '{"asked": "L1正則化つき回帰・L2正則化つき回帰、それぞれの呼び名を問う。", "point": "「L1正則化つき回帰=ラッソ回帰」「L2正則化つき回帰=リッジ回帰」とセットで覚える。", "kid": "ふつうの回帰に、重みを0にまで削る罰則(L1)を足したのがラッソ回帰。重みをなだらかに小さくする罰則(L2)を足したのがリッジ回帰。", "eg": "荷物を減らすとき、要らない物を思い切って手放すのがラッソ回帰(0にする)。全部の荷物を少しずつ軽くするのがリッジ回帰(なだらかに小さくする)というイメージ。", "terms": [["ラッソ回帰", "Lasso＝Least Absolute Shrinkage and Selection Operator。L1正則化を組み合わせ、一部の係数を0にして特徴量を選ぶ回帰"], ["リッジ回帰", "L2正則化を組み合わせ、係数全体をなだらかに小さくする回帰"]], "think": "なぜ同じ「正則化つき回帰」でも呼び名が2つに分かれるのかがカギ。回帰モデルに単にL1正則化を足しただけではまだ一般名詞だが、この組み合わせが特徴量選択の手段として広く使われるようになり、固有の名前としてラッソ回帰と呼ばれるようになった。同様に回帰にL2正則化を足した組み合わせもリッジ回帰という固有の名前を持つ。つまりこの2つは「正則化の種類（L1かL2か）」と「対象がいつも回帰であること」がセットになった、具体的な手法の名前である。", "vs": "決定木と勾配ブースティングは枝分かれによる予測とその逐次的な改良を指し、正則化つき回帰とは別系統の手法。主成分分析とk-means法はそれぞれ次元削減と教師なしのクラスタリングで、回帰でも正則化でもない。バギングとブースティングはアンサンブル学習の代表的な2方式で、こちらも回帰への正則化の組み合わせを指す語ではない。", "why_asked": "L1正則化・L2正則化という理論の名前と、それを回帰に組み合わせた「ラッソ回帰」「リッジ回帰」という具体的な手法名を結びつけられるかが問われる。", "usecase": "多数の特徴量がある回帰モデルで、効かない特徴量を自動的に削りたいときはラッソ回帰、特徴量同士が似ていて重みが不安定になりやすいときはリッジ回帰を選ぶ、という実務判断に使う。", "opt": ["正解。順にL1正則化つき回帰(ラッソ回帰)、L2正則化つき回帰(リッジ回帰)と呼ばれる。", "枝分かれによる予測とその逐次的な改良を指し、正則化つき回帰とは別系統の手法。", "次元削減と教師なしのグループ分けを指す語で、回帰でも正則化でもない。", "アンサンブル学習の代表的な2方式を指す語で、回帰への正則化の組み合わせではない。"]}'),  ('g-kentei-h-q10', '4. ディープラーニングの概要',
   '多層のニューラルネットワークで誤差が生じたとき、「どの層のどの重みが、その誤差にどれだけ責任を持つか」を割り出す必要がある。誤差逆伝播法が解決した、この課題を指す語はどれか。',
   NULL::text,
   '["信用割当問題（誤差の責任をどの重みにどれだけ割り振るかという課題）", "勾配消失問題（誤差の合図が手前の層までだんだん届かなくなる問題全般）", "過学習（訓練データの細部に寄りすぎて未知データに弱くなる状態のこと）", "次元の呪い（扱う次元が増えるほどデータがまばらになっていく問題）"]',
   0,
   '[0]',
   'single',
   '{"asked": "「どの重みに誤差の責任があるか」を割り出す課題の名前を問う。", "point": "「誤差の責任をどの重みにどれだけ配分するか」の課題が信用割当問題。", "kid": "テストの点数が悪かったとき、「どの科目の、どの単元の勉強不足が、どれだけ点数の悪さに効いたか」を突き止めるようなもの。ネットワークでは、これを各層の各重みについて行う必要がある。", "eg": "グループ作業の成果がいまいちだったとき、誰が何をどれだけサボったせいかを1人ずつ割り出すイメージ。人数が多く役割が入り組んでいるほど、この割り出し作業は難しくなる。", "terms": [["信用割当問題", "credit assignment problem。結果の良し悪しに対して、どの要素(重み)がどれだけ貢献・責任を持つかを割り出す課題"], ["連鎖律", "微分の変化率を鎖のようにかけ合わせる数学の考え方。誤差逆伝播法はこれを使って信用割当問題を解く"]], "think": "なぜ多層になるとこの問題が難しくなるのかがカギ。ネットワークが1層だけなら、出力の誤差から直接その層の重みを直せばよい。しかし層が増えると、最終的な誤差は途中の何層もの重みが折り重なって生まれた結果であり、「この誤差のうち、3層目のこの重みがどれだけ悪さをしたか」を単純には切り分けられない。これが信用割当問題である。誤差逆伝播法は、連鎖律という微分の性質を使い、出力側の誤差を1層ずつさかのぼりながら、各層各重みの「責任の大きさ(勾配)」を効率よく計算することで、この問題を実用的に解決した。", "vs": "勾配消失問題は、信用割当問題を解く過程で層が深すぎると起きる副作用であり、責任の割り出し自体を指す語ではない。過学習は訓練データへの寄りすぎであり、重みの責任配分の課題とは別の話。次元の呪いはデータの次元数が増えることで起きる問題で、こちらも重みの責任配分とは無関係。", "why_asked": "「誤差逆伝播法が何をする手法か」は覚えていても、それが解決している「信用割当問題」という課題の名前までは押さえていない受験者が多く、用語の結びつけを問う定番。", "usecase": "多層のネットワークがなぜ誤差逆伝播法という特別な計算方法を必要とするのか、その理由を説明するときの土台になる。", "opt": ["正解。誤差の責任をどの重みにどれだけ割り振るかという課題のこと。", "誤差の合図が手前の層まで届かなくなる問題で、信用割当問題を解く過程で起きる別の副作用。", "訓練データに寄りすぎて未知データに弱くなる状態で、重みの責任配分の課題とは別の話。", "次元が増えるほどデータがまばらになる問題で、重みの責任配分とは無関係。"]}'),  ('g-kentei-h-q11', '4. ディープラーニングの概要',
   'パラメータごとにこれまでの勾配の大きさを溜め込み、よく動いた方向ほど学習率を自動的に小さくしていく最適化手法だが、更新を重ねるうちに溜め込みが増えすぎて学習率がほぼ0になり、学習が止まってしまう欠点を持つものはどれか。',
   NULL::text,
   '["AdaGrad（方向ごとに学習率を自動調整する最適化手法）", "モメンタム（前回までの更新の勢いを引き継いで進む最適化手法）", "RMSprop（勾配の溜め込みを直近の情報だけに絞った最適化手法）", "Adam（モメンタムとRMSpropを組み合わせた最適化手法）"]',
   0,
   '[0]',
   'single',
   '{"asked": "方向ごとに学習率を自動調整するが、溜め込みすぎて止まる欠点を持つ最適化手法の名前を問う。", "point": "「勾配を溜め込んで学習率を自動調整」「溜まりすぎて止まる」と来たらAdaGrad。", "kid": "よく動く方向は「もう十分動いたから歩幅を小さくしよう」、あまり動かない方向は「まだ歩幅を大きくしていいよ」と、方向ごとに歩幅(学習率)を自動で変えていく工夫。ただし歩くほど歩幅がどんどん小さくなり、最後にはほぼ止まってしまう。", "eg": "毎日の運動記録を貯金箱のように積み上げていき、貯金が増えるほど「もう十分やったから今日は少しでいい」と歩幅を減らしていくイメージ。貯金がどんどん増えると、いずれ歩幅がほぼゼロになってしまう。", "terms": [["AdaGrad", "Adaptive Gradient Algorithm＝適応的勾配アルゴリズム。パラメータごとに勾配の溜め込みに応じて学習率を自動調整する手法"], ["学習率", "一回の更新で重みをどれだけ動かすかを決める値"]], "think": "なぜAdaGradは止まってしまうのかがカギ。AdaGradは各パラメータについて、これまでの勾配の2乗を足し合わせ続け、その合計が大きいほど学習率を小さくする。よく動く方向ほど早く歩幅を絞り、あまり動かない方向は歩幅を保つという工夫自体は理にかなっている。しかし勾配の2乗の合計は更新のたびに増え続ける一方で、決して減ることがない。学習が進むほどこの合計はどんどん大きくなり、やがて学習率がほぼ0まで押しつぶされてしまい、まだ谷底に着いていなくても実質的に学習が止まる。この欠点を、直近の勾配だけを重視する形に直したのがRMSpropである。", "vs": "モメンタムは前回までの更新の勢いを引き継いで進む工夫で、方向ごとに学習率を自動調整するAdaGradとは別の発想。RMSpropはAdaGradと同じく勾配ごとの溜め込みを使うが、古い勾配の影響を徐々に薄めることで溜まりすぎを防いだ改良版。AdamはモメンタムとRMSpropを組み合わせた手法で、AdaGradの欠点はすでに解消されている。", "why_asked": "「学習率を自動調整する」という利点だけを覚えて、「溜め込みすぎて止まる」という欠点とセットで理解できていないと、RMSpropやAdamとの発展順を問う問題で混同しやすい。", "usecase": "疎な特徴量が多いデータ（一部の特徴だけがまれに現れるようなデータ）で、特徴ごとに歩幅を変えたい場面の出発点として理解しておく。", "opt": ["正解。方向ごとに勾配を溜め込み学習率を自動調整するが、溜まりすぎて止まる欠点を持つ。", "前回までの更新の勢いを引き継いで進む工夫で、方向ごとの学習率自動調整とは別の発想。", "勾配の溜め込みを直近の情報だけに絞った手法で、AdaGradの溜まりすぎる欠点を改良したもの。", "モメンタムとRMSpropを組み合わせた手法で、AdaGradの欠点はすでに解消されている。"]}'),  ('g-kentei-h-q12', '4. ディープラーニングの概要',
   'Adam系の最適化手法には発展形がいくつかある。そのうち、学習の終盤で更新の動きを確率的勾配降下法(SGD)に近い形へ滑らかに近づけることで、汎化性能が落ちやすいというAdamの弱点を和らげようとした手法はどれか。',
   NULL::text,
   '["AdaBound（学習の終盤でSGD相当の動きへ滑らかに近づける手法）", "AdaDelta（AdaGradの勾配の溜め込みを直近の情報だけに絞る手法）", "AMSBound（AMSGradにAdaBoundと同じ終盤の工夫を組み合わせた手法）", "RMSprop（勾配の溜め込みを直近の情報だけに絞る最適化手法）"]',
   0,
   '[0]',
   'single',
   '{"asked": "Adam系の発展形のうち、学習終盤でSGD相当へ近づける手法の名前を問う。", "point": "「終盤でSGD相当へ滑らかに切り替える」と来たらAdaBound。", "kid": "Adamは学習が速い代わりに、たまに最後まで安定しきらないことがある。AdaBoundは、学習の終わりに近づくにつれて、昔ながらの手堅いSGDのような動きへそっと切り替えていく工夫。", "eg": "最初はスクーターで素早く移動し(Adamの速さ)、目的地に近づいたら自転車並みの慎重な速度に切り替える(SGD相当へ)イメージ。切り替えを急にせず、徐々に行うのがポイント。", "terms": [["Adam", "Adaptive Moment Estimation。モメンタムとRMSpropを組み合わせた代表的な最適化手法"], ["SGD", "Stochastic Gradient Descent＝確率的勾配降下法。一部のデータから勾配を計算し重みを更新する最も基本的な最適化手法"], ["汎化性能", "訓練データだけでなく、見たことのない未知のデータに対してもうまく機能する力"]], "think": "なぜAdamの終盤にSGDへ寄せる工夫が必要なのかがカギ。Adamは学習率を自動調整するため序盤から中盤にかけて速く進めるが、その調整の仕方によっては最後まで学習率が不安定に振れ続け、SGDでじっくり学習させた場合より汎化性能（未知データでの成績）が劣ることがあると報告された。AdaBoundは、学習率の上限と下限を少しずつ狭めていき、終盤には学習率がほぼ一定になるようにすることで、実質的にSGDに近い挙動へ滑らかに移行させる。これにより、Adamの速さとSGDの安定した終盤の両方の良さを取り込もうとした。", "vs": "AdaDeltaはAdaGradの「勾配を溜め込みすぎて学習率が0に近づく」欠点を、直近の勾配だけを重視する形に直した手法で、終盤にSGDへ寄せる工夫ではない。AMSBoundはAMSGrad（Adamの改良版の1つ）に、AdaBoundと同じ終盤の工夫を組み合わせたもの。RMSpropもAdaGradの溜め込みすぎを直した手法で、Adamの構成要素の1つに使われている。", "why_asked": "Adam系の派生手法はカタカナや英字の名前が似通っており、それぞれが「何を直そうとしたのか」を区別できているかが問われる。", "usecase": "Adamで学習させたモデルの汎化性能が思うように伸びないとき、終盤の挙動をSGDに近づける代替手法の候補として知っておく。", "opt": ["正解。学習の終盤でSGD相当の動きへ滑らかに近づけ、Adamの汎化性能の弱点を和らげる。", "AdaGradの勾配の溜め込みすぎを直近の情報だけに絞って直した手法で、終盤の工夫とは別。", "AMSGradにAdaBoundと同じ終盤の工夫を組み合わせた手法で、AdaBound自体とは別の派生形。", "勾配の溜め込みを直近の情報だけに絞る手法で、Adamの構成要素の1つとして使われている。"]}'),  ('g-kentei-h-q13', '4. ディープラーニングの概要',
   '誤差を表す地形のうち、あたりを見渡す限りでは一番低く見えても、地形全体で見ると本当の最下点ではない地点を「局所最適解」と呼ぶ。これに対し、地形全体で本当に一番低い地点を指す語はどれか。',
   NULL::text,
   '["大域最適解（地形全体で本当に一番低い地点）", "鞍点（ある方向は下り坂、別の方向は上り坂になっている地点）", "初期値（学習を始める前に各重みへ与える最初の値）", "学習率（一回の更新で重みをどれだけ動かすかを決める値）"]',
   0,
   '[0]',
   'single',
   '{"asked": "地形全体で本当に一番低い地点を指す語を問う。", "point": "「見渡す限りの底」が局所最適解、「地形全体で本当の底」が大域最適解。", "kid": "山の中を歩いていて「このあたりでは一番低い」と思っても、実は別の場所にもっと低い谷があるかもしれない。地形全体を見たときに本当に一番低い場所が大域最適解。", "eg": "町の中を歩いて「このあたりでは一番低い場所」を見つけても、地図全体で見ると別の町にもっと低い場所があるかもしれない。地図全体で本当に一番低い場所を探すのが大域最適解を見つけること。", "terms": [["局所最適解", "あたりを見渡す限りでは一番低いが、地形全体で見ると本当の最下点ではない地点"], ["鞍点", "ある方向には下り坂、別の方向には上り坂になっている、馬の鞍のような形の地点"]], "think": "なぜこの2つを区別する必要があるのかがカギ。勾配降下法は「今いる場所から見て下り坂の方向へ進む」というその場の情報だけを頼りに進む。そのため、あたり一帯を見渡す限り下り坂がどこにもない地点にたどり着くと、そこで足を止めてしまう。しかしその地点は、地形全体で見ればまだ他にもっと低い谷があるかもしれない「局所最適解」にすぎないことがある。地形全体で本当に一番低い地点である大域最適解にたどり着けたかどうかは、その場の情報だけでは判断できない。この区別があるからこそ、モメンタムのように勢いを使って浅い谷を乗り越える工夫が意味を持つ。", "vs": "鞍点はある方向は下り坂、別の方向は上り坂になっている地点で、局所最適解とは形が異なるが、どちらも勾配がほぼ0になり学習が止まりやすい点で紛らわしい。初期値は学習を始める前に重みへ与える最初の値で、地形上のどの地点から出発するかを決めるものであり、地形の底そのものを指す語ではない。学習率は一回の更新でどれだけ動くかを決める値で、こちらも地形の底の名前ではない。", "why_asked": "「局所最適解」だけを覚えていると、その対になる「大域最適解」という語や、似て非なる「鞍点」との違いを問われたときに答えられなくなるため。", "usecase": "モデルの学習がある地点で成績の改善が止まったとき、それが局所最適解なのか鞍点なのかを見分け、モメンタムや学習率の調整などの対策を選ぶ判断材料になる。", "opt": ["正解。地形全体で見て本当に一番低い地点のこと。", "ある方向は下り坂、別の方向は上り坂になっている地点で、局所最適解とは形が異なる。", "学習を始める前に重みへ与える最初の値で、地形のどこから出発するかを決めるだけの値。", "一回の更新で重みをどれだけ動かすかを決める値で、地形の底の名前ではない。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">見渡した範囲での底と、地形全体での底</text><path d=\"M20 40 C 60 100, 90 100, 120 55 C 150 20, 180 105, 210 120 C 240 130, 270 90, 320 30\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.5\"/><circle cx=\"105\" cy=\"88\" r=\"4\" fill=\"#c9a04a\" stroke=\"#c9a04a\" stroke-width=\"1.3\" opacity=\"0.6\"/><text x=\"105\" y=\"108\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">局所最適解</text><circle cx=\"222\" cy=\"126\" r=\"4\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.6\"/><text x=\"222\" y=\"138\" fill=\"#6ab08d\" font-size=\"8.5\" text-anchor=\"middle\">大域最適解</text><text x=\"170\" y=\"24\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">まわりより低いだけの谷と、一番低い谷がある</text></svg>"}'),  ('g-kentei-h-q14', '4. ディープラーニングの概要',
   'モデルを複雑にしていくと、検証誤差はいったん下がったのち過学習で上がるのが従来の常識だったが、さらにモデルを大きくし続けると、上がった検証誤差が再び下がっていく現象が近年報告されている。これを指す語はどれか。',
   NULL::text,
   '["二重降下現象（検証誤差が一度悪化した後、再び下がる現象）", "早期終了（検証誤差が悪化し始めた時点で学習を打ち切る対策）", "バイアス・バリアンストレードオフ（単純さと複雑さの間の従来型の関係）", "過学習（訓練データに寄りすぎて検証誤差が悪化する状態）"]',
   0,
   '[0]',
   'single',
   '{"asked": "検証誤差が下がって上がってまた下がる現象の名前を問う。", "point": "「一度悪化した検証誤差が、モデルをさらに大きくすると再び下がる」なら二重降下現象。", "kid": "モデルを複雑にしていくと、最初は検証の成績が良くなり、次に行き過ぎて悪くなる（過学習）。ふつうはここで話が終わるが、実はモデルをもっともっと大きくし続けると、悪くなった成績がまた良くなっていくことがある。この「良くなる→悪くなる→また良くなる」の2段落ちを二重降下現象と呼ぶ。", "eg": "山を1つ越えたら谷底だと思っていたら、実はその先にもう1つ山があり、それを越えるとさらに低い谷にたどり着いた、というイメージ。", "terms": [["二重降下現象", "double descent。検証誤差が一度悪化した後、モデルをさらに大きくすると再び下がっていく現象"], ["バイアス・バリアンストレードオフ", "モデルが単純すぎて外す誤り(バイアス)と、複雑すぎてブレる誤り(バリアンス)は一方を抑えると他方が増えやすいという従来の関係"]], "think": "なぜ従来の常識とぶつかるのかがカギ。従来のバイアス・バリアンストレードオフの考え方では、モデルを複雑にするほど訓練誤差は下がり続けるが、検証誤差はある地点を境に過学習で悪化していくとされ、そこで複雑さを止めるのが定石だった。ところが近年、ニューラルネットワークのようにパラメータ数が非常に多いモデルでは、検証誤差が過学習で一度悪化したあとも、モデルをさらに大きくし続けると、検証誤差が再び下がっていくケースが観測された。つまり「複雑さを増やすほど悪くなる一方」ではなく、ある山を越えた先にもっと良い状態があることがあり、これが二重降下現象と呼ばれる。", "vs": "早期終了は検証誤差が悪化し始めた時点で学習を打ち切る対策であり、二重降下現象を知らずにこの対策だけを機械的に行うと、悪化の先にある改善のチャンスを逃す可能性がある。バイアス・バリアンストレードオフは複雑さと誤差の従来型の関係を指す語で、二重降下現象はこの従来の関係だけでは説明できない例外的な観察を指す。過学習は検証誤差の悪化そのものを指す状態で、二重降下現象の途中経過の一部にすぎない。", "why_asked": "「複雑にしすぎると必ず過学習する」という従来の常識だけで止まっていると、この現象を知らないため、近年の理論の追加として出題されやすい。", "usecase": "巨大なモデルを扱う際に、検証誤差が悪化した段階で開発を諦めるのではなく、さらに規模を増やす選択肢もありうることを理解する材料になる。", "opt": ["正解。検証誤差が一度悪化した後、モデルをさらに大きくすると再び下がっていく現象。", "検証誤差が悪化し始めた時点で学習を打ち切る対策で、二重降下現象を知らないと機会を逃しうる。", "単純さと複雑さの間の従来型の関係を指す語で、二重降下現象はこの関係の例外的な観察。", "訓練データに寄りすぎて検証誤差が悪化する状態で、二重降下現象の途中経過の一部にすぎない。"], "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">検証誤差が下がって→上がって→また下がる</text><path d=\"M20 110 C 50 40, 80 30, 110 55 C 140 80, 150 108, 180 118 C 210 126, 250 100, 320 35\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.6\"/><circle cx=\"110\" cy=\"55\" r=\"3.5\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"110\" y=\"42\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">1回目の底</text><circle cx=\"180\" cy=\"118\" r=\"3.5\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.3\"/><text x=\"180\" y=\"132\" fill=\"#c47070\" font-size=\"8\" text-anchor=\"middle\">過学習で悪化</text><circle cx=\"300\" cy=\"45\" r=\"3.5\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"255\" y=\"25\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">さらに大きくすると</text><text x=\"255\" y=\"34\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">再び改善</text><line x1=\"20\" y1=\"135\" x2=\"320\" y2=\"135\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"170\" y=\"145\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">モデルの複雑さ（大きさ）→</text></svg>"}'),  ('g-kentei-h-q15', '4. ディープラーニングの概要',
   '手元のメモリに乗り切らないほど大きい訓練データがあり、しかも新しいデータが少しずつ絶え間なく届き続ける状況で、重みの更新方法として最も適切なものはどれか。',
   NULL::text,
   '["オンライン学習（データが届くたびに1件ずつ重みを更新する方式）", "バッチ学習（訓練データ全体を1つのかたまりとして使い切ってから重みを更新する方式）", "ミニバッチ学習（データを一定数の小さな束に分けて順に重みを更新する方式）", "早期終了（検証誤差の悪化を見て学習を打ち切る対策）"]',
   0,
   '[0]',
   'single',
   '{"asked": "メモリに乗り切らず、新データが絶え間なく届く状況に合う更新方式を問う。", "point": "「全部を貯め込めず、データが届くたび」ならオンライン学習。", "kid": "オンライン学習は、データが1件届くたびにその場で重みを直す方式。バッチ学習は全部のデータを1回貯めてからまとめて重みを直す方式。ミニバッチ学習はその中間で、少しずつ束にして直す方式。", "eg": "オンライン学習は、注文が入るたびにその場で1つずつ調理する屋台。バッチ学習は、1日分の注文を全部集めてからまとめて調理する仕出し弁当。ミニバッチ学習は、数人分ずつまとめて調理する定食屋のイメージ。", "terms": [["オンライン学習", "訓練データを1件ずつ受け取り、そのたびに重みを更新していく学習方式"], ["バッチ学習", "訓練データ全体を1つのかたまりとして使い切ってから、まとめて重みを更新する学習方式"], ["ミニバッチ学習", "訓練データを一定数の小さな束(ミニバッチ)に分け、束ごとに順番に重みを更新する学習方式"]], "think": "なぜこの場面ではオンライン学習が合うのかがカギ。バッチ学習は訓練データ全体を一度にメモリへ乗せる必要があるため、そもそもメモリに乗り切らないほど大きいデータには使えない。ミニバッチ学習は小さな束に分けることでメモリの問題をある程度和らげられるが、それでも「あらかじめ全データが手元にそろっている」ことを前提にした考え方であり、新しいデータが絶え間なく届き続ける状況には向いていない。オンライン学習は、データが1件届くたびにその場で使い切って重みを更新し、そのデータは貯め込まない。だから、メモリに乗らないほど大きく、かつ流れ続けるデータには最も適している。", "vs": "バッチ学習は全データを一度に扱える環境で、更新の方向が安定しやすい代わりに、メモリに乗り切らない巨大データや流れ続けるデータには使えない。ミニバッチ学習はバッチ学習とオンライン学習の中間で、多くの実務ではこれが標準的に使われるが、今回のように「新しいデータが絶え間なく届く」という条件までは満たしにくい。早期終了は更新方式ではなく、検証誤差の悪化を見て学習を打ち切るタイミングの工夫であり、この場面の答えにはならない。", "why_asked": "3つの更新方式の定義だけを暗記していると答えられるが、この問題のように具体的な制約(メモリ・データの届き方)から逆に方式を選ばせる場面判断では、定義の丸暗記だけでは対応できないため。", "usecase": "センサーやアクセスログのように、データが絶え間なく生成され全部を貯めておけない状況で、モデルをその場その場で少しずつ賢くしていきたいときに使う。", "opt": ["正解。データが届くたびに1件ずつ重みを更新する方式で、メモリに乗らない流れ続けるデータに合う。", "訓練データ全体を1つのかたまりとして使い切ってから重みを更新する方式で、巨大データには使えない。", "データを一定数の小さな束に分けて順に重みを更新する方式で、全データがそろっている前提に近い。", "検証誤差の悪化を見て学習を打ち切る対策で、重みの更新方式そのものではない。"]}'),  ('g-kentei-h-q16', '4. ディープラーニングの概要',
   '汎用的な逐次処理は得意だが並列演算はさほど得意でないCPU、画像処理向けの並列計算を得意とするGPUに対し、行列演算の並列処理に特化し、ディープラーニング専用に設計された演算装置はどれか。',
   NULL::text,
   '["TPU（ディープラーニングの行列演算に特化して設計された専用の演算装置）", "CPU（逐次処理は得意だが並列演算はさほど得意でない汎用の演算処理装置）", "GPU（もともと画像処理向けに開発され並列演算を得意とする演算装置）", "FPGA（回路の構成をあとから書き換えられる用途の広い集積回路）"]',
   0,
   '[0]',
   'single',
   '{"asked": "行列演算に特化し、ディープラーニング専用に設計された演算装置の名前を問う。", "point": "「行列演算に特化」「ディープラーニング専用設計」ならTPU。", "kid": "CPUは何でもこなせるが1つ1つを順番に処理するのが得意な万能選手。GPUは同じ計算をたくさん同時にこなすのが得意。TPUはその中でも、ディープラーニングでよく出てくる行列どうしの掛け算だけに絞って、とことん速くなるよう専用設計された演算装置。", "eg": "CPUは何でも屋の職人、GPUは同じ作業を大勢で一斉にこなす工場のライン、TPUはその工場の中でも「行列の掛け算」という1つの作業だけに特化した専用ラインのイメージ。", "terms": [["CPU", "Central Processing Unit＝中央演算処理装置。汎用的な逐次処理が得意な演算装置"], ["GPU", "Graphics Processing Unit＝画像処理装置。もともと画像処理向けに開発された、並列演算が得意な演算装置"], ["TPU", "Tensor Processing Unit＝テンソル処理装置。行列(テンソル)の演算に特化した、ディープラーニング専用の演算装置"]], "think": "なぜディープラーニング専用の演算装置が必要になったのかがカギ。ディープラーニングの学習は、大量の重み付き総和を何層にもわたって繰り返す計算であり、これは本質的に行列どうしの掛け算の繰り返しである。CPUは1つ1つの命令を順番にこなす逐次処理が得意なため、この種の大量の並列計算には向いていない。GPUはもともと画像の各ピクセルを同時に処理するために作られており、単純な計算を大量に同時にこなす並列性を持つため、ディープラーニングの学習にも転用され普及を後押しした。TPUはさらに踏み込んで、行列演算だけに回路を絞り込んで専用設計することで、GPUよりも効率よく行列演算をこなせるようにした演算装置である。", "vs": "CPUは汎用的な逐次処理に強いが、大量の並列な行列演算はGPUやTPUに比べて苦手。GPUはもともと画像処理向けに開発され並列演算が得意で、ディープラーニングにも広く使われるが、TPUのように行列演算だけに専用設計されているわけではない。FPGAは回路の構成をあとから書き換えられる汎用の集積回路で、用途に応じて柔軟に組み替えられる点が特徴だが、TPUのように行列演算専用に固定設計されたものではない。", "why_asked": "「GPUを使えば速い」までは知っていても、TPUがさらにディープラーニング専用に設計されている点や、CPU・GPU・TPUそれぞれの得意分野の違いを正確に区別できているかが問われる。", "usecase": "大規模なモデルの学習や推論を高速化したいとき、汎用性が要る場面ではCPU、画像やゲームなど並列演算全般ではGPU、大規模な行列演算に特化して最速を狙うクラウド環境ではTPU、というように使い分ける判断材料になる。", "opt": ["正解。行列演算に特化して設計された、ディープラーニング専用の演算装置。", "逐次処理は得意だが並列演算はさほど得意でない汎用の演算装置で、大量の行列演算には向かない。", "もともと画像処理向けに並列演算を得意とする演算装置で、行列演算専用に設計されたものではない。", "回路の構成をあとから書き換えられる汎用の集積回路で、行列演算専用に固定設計されたものではない。"]}')
) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-h'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

